CREATE VIEW theeyebeta.latest_snapshots AS
 WITH latest_cap AS (
         SELECT DISTINCT ON (market_cap_daily.instrument_id) market_cap_daily.instrument_id,
            market_cap_daily.market_cap,
            market_cap_daily.close_price,
            market_cap_daily.as_of_date
           FROM theeyebeta.market_cap_daily
          WHERE (market_cap_daily.instrument_id IS NOT NULL)
          ORDER BY market_cap_daily.instrument_id, market_cap_daily.as_of_date DESC
        ), latest_tech AS (
         SELECT DISTINCT ON (ind_technical_daily.instrument_id) ind_technical_daily.instrument_id,
            ind_technical_daily.sma_10,
            ind_technical_daily.sma_50,
            ind_technical_daily.sma_200,
            ind_technical_daily.rsi_14,
            ind_technical_daily.macd,
            ind_technical_daily.macd_signal,
            ind_technical_daily.macd_hist,
            ind_technical_daily.date
           FROM theeyebeta.ind_technical_daily
          ORDER BY ind_technical_daily.instrument_id, ind_technical_daily.date DESC
        ), ranked_ticks AS (
         SELECT ticks.instrument_id,
            ticks.ts,
            ticks.close,
            ticks.volume,
            row_number() OVER (PARTITION BY ticks.instrument_id ORDER BY ticks.ts DESC) AS rn
           FROM ( SELECT prices_daily.instrument_id,
                    prices_daily.ts,
                    prices_daily.close,
                    prices_daily.volume
                   FROM theeyebeta.prices_daily
                UNION ALL
                 SELECT prices_intraday.instrument_id,
                    prices_intraday.ts,
                    prices_intraday.close,
                    prices_intraday.volume
                   FROM theeyebeta.prices_intraday) ticks
        ), latest_tick AS (
         SELECT ranked_ticks.instrument_id,
            ranked_ticks.ts AS last_price_ts,
            ranked_ticks.close AS last_price,
            ranked_ticks.volume
           FROM ranked_ticks
          WHERE (ranked_ticks.rn = 1)
        ), ranked_daily AS (
         SELECT prices_daily.instrument_id,
            prices_daily.close,
            row_number() OVER (PARTITION BY prices_daily.instrument_id ORDER BY prices_daily.ts DESC) AS rn
           FROM theeyebeta.prices_daily
        ), prev_daily_close AS (
         SELECT ranked_daily.instrument_id,
            ranked_daily.close AS prev_close
           FROM ranked_daily
          WHERE (ranked_daily.rn = 2)
        ), latest_signal AS (
         SELECT DISTINCT ON (m.instrument_id) m.instrument_id,
            s.signal AS latest_signal
           FROM (theeyebeta.signals s
             JOIN theeyebeta.public_ticker_map m ON ((m.public_ticker_id = s.ticker_id)))
          ORDER BY m.instrument_id, s.ts DESC
        ), effective_price AS (
         SELECT COALESCE(lc_1.instrument_id, tick_1.instrument_id) AS instrument_id,
                CASE
                    WHEN (tick_1.last_price_ts IS NULL) THEN lc_1.close_price
                    WHEN (lc_1.as_of_date IS NULL) THEN tick_1.last_price
                    WHEN (tick_1.last_price_ts >= (lc_1.as_of_date)::timestamp with time zone) THEN tick_1.last_price
                    ELSE lc_1.close_price
                END AS last_price,
                CASE
                    WHEN (tick_1.last_price_ts IS NULL) THEN (lc_1.as_of_date)::timestamp with time zone
                    WHEN (lc_1.as_of_date IS NULL) THEN tick_1.last_price_ts
                    WHEN (tick_1.last_price_ts >= (lc_1.as_of_date)::timestamp with time zone) THEN tick_1.last_price_ts
                    ELSE (lc_1.as_of_date)::timestamp with time zone
                END AS last_price_ts
           FROM (latest_cap lc_1
             FULL JOIN latest_tick tick_1 ON ((tick_1.instrument_id = lc_1.instrument_id)))
        )
 SELECT COALESCE(lc.instrument_id, lt.instrument_id, tick.instrument_id) AS instrument_id,
    lc.market_cap,
    ep.last_price,
    ep.last_price_ts,
        CASE
            WHEN ((pdc.prev_close IS NOT NULL) AND (pdc.prev_close <> (0)::numeric)) THEN (((ep.last_price - pdc.prev_close) / pdc.prev_close) * (100)::numeric)
            ELSE NULL::numeric
        END AS price_change_pct,
        CASE
            WHEN (pdc.prev_close IS NOT NULL) THEN (ep.last_price - pdc.prev_close)
            ELSE NULL::numeric
        END AS price_change_abs,
    tick.volume,
    lt.sma_10,
    lt.sma_50,
    lt.sma_200,
    lt.rsi_14,
    lt.macd,
    lt.macd_signal,
    lt.macd_hist,
    sig.latest_signal,
    (LEAST(lc.as_of_date, lt.date))::timestamp with time zone AS updated_at
   FROM (((((latest_cap lc
     FULL JOIN latest_tech lt ON ((lt.instrument_id = lc.instrument_id)))
     FULL JOIN latest_tick tick ON ((tick.instrument_id = COALESCE(lc.instrument_id, lt.instrument_id))))
     LEFT JOIN prev_daily_close pdc ON ((pdc.instrument_id = COALESCE(lc.instrument_id, lt.instrument_id, tick.instrument_id))))
     LEFT JOIN latest_signal sig ON ((sig.instrument_id = COALESCE(lc.instrument_id, lt.instrument_id, tick.instrument_id))))
     LEFT JOIN effective_price ep ON ((ep.instrument_id = COALESCE(lc.instrument_id, lt.instrument_id, tick.instrument_id))));

