    time_in_force text DEFAULT 'day'::text NOT NULL,
    status text DEFAULT 'pending_approval'::text NOT NULL,
    approved_by text,
    approved_at timestamp with time zone,
    submitted_at timestamp with time zone,
    filled_qty numeric(20,6) DEFAULT 0 NOT NULL,
    avg_fill_price numeric(18,6),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    submitted_by text,
    CONSTRAINT orders_order_type_check CHECK ((order_type = ANY (ARRAY['market'::text, 'limit'::text, 'stop'::text, 'stop_limit'::text, 'trailing_stop'::text]))),
    CONSTRAINT orders_side_check CHECK ((side = ANY (ARRAY['buy'::text, 'sell'::text]))),
    CONSTRAINT orders_status_check CHECK ((status = ANY (ARRAY['pending_approval'::text, 'approved'::text, 'submitted'::text, 'accepted'::text, 'partially_filled'::text, 'filled'::text, 'cancelled'::text, 'rejected'::text, 'expired'::text])))
);

CREATE TABLE theeyebeta.positions (
    id bigint NOT NULL,
    portfolio_id uuid NOT NULL,
    instrument_id bigint NOT NULL,
    qty numeric(20,6) NOT NULL,
    avg_entry_price numeric(18,6) NOT NULL,
    market_value numeric(20,6),
    unrealized_pnl numeric(20,6),
    realized_pnl numeric(20,6),
    opened_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE SEQUENCE theeyebeta.positions_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE theeyebeta.positions_id_seq OWNED BY theeyebeta.positions.id;

CREATE TABLE theeyebeta.sector_daily (
    sector text NOT NULL,
    as_of_date date NOT NULL,
    n_instruments integer DEFAULT 0 NOT NULL,
    avg_return_1d numeric(12,6),
    avg_return_5d numeric(12,6),
    avg_return_30d numeric(12,6),
    median_rsi_14 numeric(8,4),
    pct_above_sma_50 numeric(6,4),
    pct_above_sma_200 numeric(6,4),
    rel_strength_spx_30d numeric(12,6),
    rotation_rank smallint,
    volume_ratio_20d numeric(12,6),
    top_contributors jsonb DEFAULT '[]'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE SEQUENCE theeyebeta.signals_signal_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
