    notes text
);

CREATE TABLE theeyebeta.trask_components (
    id integer NOT NULL,
    component_type character varying(32) NOT NULL,
    component_id character varying(64) NOT NULL,
    display_name character varying(128) NOT NULL,
    state character varying(32) DEFAULT 'STOPPED'::character varying NOT NULL,
    last_heartbeat timestamp with time zone,
    last_state_change timestamp with time zone DEFAULT now() NOT NULL,
    error_count integer DEFAULT 0 NOT NULL,
    restart_count integer DEFAULT 0 NOT NULL,
    config jsonb DEFAULT '{}'::jsonb NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT trask_components_valid_state CHECK (((state)::text = ANY ((ARRAY['STOPPED'::character varying, 'STARTING'::character varying, 'RUNNING'::character varying, 'DEGRADED'::character varying, 'STOPPING'::character varying, 'FAILED'::character varying, 'RETIRED'::character varying])::text[])))
);

CREATE SEQUENCE theeyebeta.trask_components_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE theeyebeta.trask_components_id_seq OWNED BY theeyebeta.trask_components.id;

CREATE TABLE theeyebeta.worker_heartbeats (
    worker_id character varying(64) NOT NULL,
    worker_type character varying(32) NOT NULL,
    status character varying(16) NOT NULL,
    last_heartbeat timestamp with time zone DEFAULT now() NOT NULL,
    started_at timestamp with time zone,
    restart_count integer DEFAULT 0,
    last_error text,
    metadata jsonb,
    CONSTRAINT worker_heartbeats_status_check CHECK (((status)::text = ANY ((ARRAY['running'::character varying, 'stopped'::character varying, 'failed'::character varying, 'restarting'::character varying, 'retired'::character varying])::text[])))
);

